import React from "react"
import { BookOpenIcon, CodeIcon, FlaskIcon, PlayIcon, PuzzlePieceIcon } from "@phosphor-icons/react"
import { Toolbar, type ToolbarTabItem } from "@/components/composites/navigation/Toolbar"

/**
 * `ContentModeNav` — how to view this lesson: modes on the left, code language
 * on the right. Switching mode changes the route, so this is navigation, not a
 * tab/panel pair. A locked mode renders muted but still fires `onModeChange` —
 * the screen decides a locked tap opens the paywall. The mode group carries the
 * one accent; the language group is neutral. No `isSkeleton` — it is static
 * chrome. The right group appearing is its own leaf; selected mode and lock
 * state are data.
 */

/** The ways a lesson can be looked at. */
export type ContentMode = "content" | "sandbox" | "challenges" | "aiLab"

/**
 * Label + icon per mode. The BLOCK owns this table: it is the vocabulary of the
 * reading experience, and a caller that could pass it would own the wording.
 */
const MODE_LABEL: Record<ContentMode, string> = {
    content: "Content",
    sandbox: "Sandbox",
    challenges: "Challenges",
    aiLab: "AI Lab",
}

// `size-5` — the tab's own text is `text-sm` (HeroUI `Tabs.Tab` default, `tabs.css`
// `.apply ... text-sm`), and this icon sits INSIDE that control, so it matches the
// control's own box height (line-height 20px), not the bare glyph size (§5a icon=DIV
// case) — `size-3.5` would be the icon=TEXT pairing, wrong for an icon inside a tab.
const MODE_ICON: Record<ContentMode, React.ReactNode> = {
    content: <BookOpenIcon aria-hidden focusable="false" className="size-5" />,
    sandbox: <PlayIcon aria-hidden focusable="false" className="size-5" />,
    challenges: <PuzzlePieceIcon aria-hidden focusable="false" className="size-5" />,
    aiLab: <FlaskIcon aria-hidden focusable="false" className="size-5" />,
}

// Same icon on every language tab (doesn't distinguish TS from Go) — the trigger
// affordance for "this collapses to a language switcher" below `@app-sm`, not a
// per-language mark. Matches `Toolbar`'s own collapsed-group story convention
// (`RightNeutralCollapsed`, every item sharing one `GlobeIcon`) — the collapsed
// `Select` trigger is ICON-ONLY (§13c), so a language row with no icon of its own
// would render a blank trigger once `collapseRightOnMobile` is on.
const LANGUAGE_ICON = <CodeIcon aria-hidden focusable="false" className="size-4" weight="bold" />

/** One offered mode — whether it is locked. */
export interface ContentModeOption {
    /** Which mode this entry is. */
    mode: ContentMode
    /** `true` → premium and not yet bought: rendered muted, still clickable. */
    isLocked?: boolean
}

/** One entry in the fixed code-language catalog. */
export interface ContentLanguage {
    /** Stable id used as the selection key, e.g. `"typescript"`. */
    key: string
    /** Display label, already localized by the caller. */
    label: string
    /** `true` → this lesson has no body in this language: rendered disabled, not omitted. */
    isDisabled?: boolean
}

/** Props for {@link ContentModeNav}. */
export interface ContentModeNavProps {
    /** Modes this lesson offers, in display order. */
    modes: Array<ContentModeOption>
    /** Which mode is being looked at now. */
    mode: ContentMode
    /**
     * Fired with the mode the reader picked — INCLUDING a locked one. The screen
     * decides what a locked pick means (typically: open the paywall instead of
     * navigating). The block never swallows the event.
     */
    onModeChange: (mode: ContentMode) => void
    /**
     * The FULL fixed language catalog (TypeScript/Java/C#/Go, in that order),
     * each carrying its own `isDisabled` — a lesson missing a language still
     * lists it, dimmed, rather than shrinking the row (real `src` never hides
     * a language, only greys it out). Fewer than two AVAILABLE (non-disabled)
     * entries → the right group is not drawn at all: a switcher with one live
     * option is a control that cannot do anything.
     */
    languages?: Array<ContentLanguage>
    /** Which language is being read. */
    language?: string
    /** Fired with the language the reader picked. */
    onLanguageChange?: (language: string) => void
    /**
     * Accessible name for the mode row, localized by the caller (blocks carry no
     * i18n). Without it a screen reader hears loose tabs.
     */
    ariaLabel: string
    /** Accessible name for the language group. Required whenever `languages` is set. */
    languageAriaLabel?: string
}

/**
 * The lesson's mode row. See the file header for why locked modes stay clickable
 * and why this is navigation rather than a tab/panel pair.
 *
 * @param props - {@link ContentModeNavProps}
 */
const ContentModeNav = ({
    modes,
    mode,
    onModeChange,
    languages,
    language,
    onLanguageChange,
    ariaLabel,
    languageAriaLabel,
}: ContentModeNavProps) => {
    const items: Array<ToolbarTabItem> = modes.map((entry) => ({
        key: entry.mode,
        label: MODE_LABEL[entry.mode],
        icon: MODE_ICON[entry.mode],
        // MUTED, not disabled: a locked mode must still receive the click so the
        // screen can open the offer. Disabling it kills the very thing this row is for.
        muted: entry.isLocked,
    }))

    // A switcher with one AVAILABLE option is a control that cannot do anything — count
    // only the non-disabled entries, since the catalog itself always lists all four.
    const availableLanguageCount = (languages ?? []).filter((entry) => !entry.isDisabled).length
    const hasLanguages = availableLanguageCount > 1 && language != null && onLanguageChange != null

    return (
        <Toolbar
                    leftTabs={{
                        items,
                        selectedKey: mode,
                        ariaLabel,
                        onSelectionChange: (key) => onModeChange(String(key) as ContentMode),
                    }}
                    rightTabs={
                        hasLanguages
                            ? {
                                items: (languages ?? []).map((entry) => ({
                                    key: entry.key,
                                    label: entry.label,
                                    icon: LANGUAGE_ICON,
                                    isDisabled: entry.isDisabled,
                                })),
                                selectedKey: language as string,
                                ariaLabel: languageAriaLabel ?? "",
                                onSelectionChange: (key) => onLanguageChange?.(String(key)),
                            }
                            : undefined
                    }
                    // The language group is a "same lesson, different presentation" toggle, so
                    // it stays NEUTRAL: only the mode group carries accent, and the row keeps
                    // ONE accent signal rather than two competing for the eye.
                    rightTabsNeutral
                    // A set-once preference, not a second navigation choice — folds behind a
                    // compact icon-only dropdown below `@app-sm` instead of crowding the reading
                    // column with 4 inline tabs.
            collapseRightOnMobile
        />
    )
}

export { ContentModeNav }

import React from "react"
import { StatRibbon, type StatRibbonItem } from "@/components/composites/stats/StatRibbon"

/**
 * `PlaygroundDeviceSnapshot` — "Your machine": the paired agent's raw hardware
 * report turned into the same 4-cell `StatRibbon` the Lab route shows, so setup and
 * the live lab agree about what the machine can run. Reuses `StatRibbon`; the block
 * owns the domain judgement — bytes → GB rounding, the `win32`/`darwin`/`linux` →
 * "Windows"/"macOS"/"Linux" table, and the three sentences a GPU cell can say
 * depending on which of `gpu`/`vramTotalMb`/`vramFreeMb` came back. Every
 * `deviceInfo` combination and `isSkeleton` are states of the 4-cell shape.
 */

/**
 * The paired agent's hardware/OS snapshot, exactly as it arrives over the
 * `device:info` socket message — ported faithfully from
 * `PlaygroundDeviceInfo` in
 * `src/components/features/learn/Playground/PlaygroundPrepare/index.tsx`
 * (itself mirroring `PlaygroundByomDeviceInfoSocketIoMessage`).
 */
export interface PlaygroundDeviceInfo {
    /** `win32` | `linux` | `darwin`. */
    platform: string
    /** CPU architecture (`x64`, `arm64`, …). */
    arch: string
    /** Machine hostname. */
    hostname: string
    /** CPU model string. */
    cpuModel: string
    /** Logical CPU core count. */
    cpuCores: number
    /** Total RAM in bytes. */
    totalMemBytes: number
    /** Free RAM in bytes (at snapshot time). */
    freeMemBytes: number
    /** First discrete GPU name, or `null` if it couldn't be read. */
    gpu: string | null
    /** Free GPU VRAM in MiB (NVIDIA only); omitted when no NVIDIA GPU. */
    vramFreeMb?: number
    /** Total GPU VRAM in MiB (NVIDIA only); omitted when no NVIDIA GPU. */
    vramTotalMb?: number
}

/** Bytes → whole GB, the unit the ribbon reads in. */
const gbOf = (bytes: number): number => Math.round(bytes / 1e9)

/**
 * Node's `process.platform` id → the name a learner recognises.
 * @param platform - `win32` / `darwin` / `linux` (or anything else, passed through).
 */
const platformLabel = (platform: string): string =>
    platform === "win32"
        ? "Windows"
        : platform === "darwin"
            ? "macOS"
            : platform === "linux" ? "Linux" : platform

/**
 * The GPU cell's detail line: total + free VRAM when the agent could read an
 * NVIDIA card, an empty second line when a GPU exists but VRAM couldn't be
 * read, or an explicit "unknown" when no GPU was detected at all — three
 * distinct facts, not one string with a blank filled in.
 */
const vramDetail = (gpu: string | null, vramTotalMb?: number, vramFreeMb?: number): string =>
    vramTotalMb
        ? `${Math.round(vramTotalMb / 1024)} GB VRAM${vramFreeMb != null ? ` · ${vramFreeMb} MB free` : ""}`
        : gpu ? "" : "couldn't read"

/**
 * One ribbon cell's label: the fixed category word, plus the computed detail
 * when there is one — `StatRibbonItem.label` is a plain `string` (the ribbon
 * renders it itself through `Typography`), so caption and detail join into a
 * single line instead of the old two-line `<span>`.
 */
const deviceStatLabel = (caption: string, detail: string): string =>
    detail ? `${caption} · ${detail}` : caption

/** Props for {@link PlaygroundDeviceSnapshot}. */
export interface PlaygroundDeviceSnapshotProps {
    /** The paired machine's hardware/OS snapshot to render as a stat ribbon. */
    deviceInfo: PlaygroundDeviceInfo
    /** `true` → every cell's value/detail line swaps to its own shimmer. */
    isSkeleton?: boolean
}

/**
 * "Your machine": the paired agent's hardware report as a 4-cell stat ribbon
 * (OS · CPU · RAM · GPU). See the file header for the unit math, the
 * platform-name table, and why this composes `StatRibbon` instead of a new
 * shape.
 *
 * @param props - {@link PlaygroundDeviceSnapshotProps}
 */
const PlaygroundDeviceSnapshot = ({
    deviceInfo,
    isSkeleton = false,
}: PlaygroundDeviceSnapshotProps) => {
    const items: ReadonlyArray<StatRibbonItem> = [
        {
            key: "os",
            value: platformLabel(deviceInfo.platform),
            label: deviceStatLabel("Operating system", `${deviceInfo.arch} · ${deviceInfo.hostname}`),
        },
        {
            key: "cpu",
            value: `${deviceInfo.cpuCores} cores`,
            label: deviceStatLabel("CPU", deviceInfo.cpuModel),
        },
        {
            key: "ram",
            value: `${gbOf(deviceInfo.totalMemBytes)} GB`,
            label: deviceStatLabel("RAM", `${gbOf(deviceInfo.freeMemBytes)} GB free`),
        },
        {
            key: "gpu",
            value: deviceInfo.gpu ?? "—",
            label: deviceStatLabel("GPU", vramDetail(deviceInfo.gpu, deviceInfo.vramTotalMb, deviceInfo.vramFreeMb)),
        },
    ]

    return (
        <StatRibbon
            valueType="body"
            isSkeleton={isSkeleton}
            items={items}
        />
    )
}

export { PlaygroundDeviceSnapshot }

import React from "react"
import { PageHeader } from "@/components/composites/layout/Page"

/**
 * `PlaygroundHubHeader` — the hub-identity cluster at the top of the
 * Docker/Kubernetes exercise grid: a title and an optional one-sentence purpose
 * line. Sibling of `ContentHeader`/`FoundationsHeader` but thinnest — no breadcrumb,
 * meta row, or secondary card. One shape: `isSkeleton` only swaps which state the
 * `Typography` renders inside the same `PageHeader`.
 */

/** Props for {@link PlaygroundHubHeader}. */
export interface PlaygroundHubHeaderProps {
    /** Hub title, e.g. "Playground". */
    title: string
    /** One-sentence purpose line explaining what the hub is for. */
    description?: string
    /**
     * `true` → the composed `Typography` slots switch to their own shimmer.
     * The flag FLOWS DOWN into the real atoms rather than building a parallel
     * skeleton tree (§12c).
     */
    isSkeleton?: boolean
}

/**
 * The playground-hub identity cluster at the top of the exercise grid. See
 * the file header for the full contract and why this stays thinner than its
 * `ContentHeader`/`FoundationsHeader` siblings.
 *
 * @param props - {@link PlaygroundHubHeaderProps}
 */
const PlaygroundHubHeader = ({
    title,
    description,
    isSkeleton = false,
}: PlaygroundHubHeaderProps) => {
    return (
        <PageHeader
            isSkeleton={isSkeleton}
            title={title}
            description={description}
        />
    )
}

export { PlaygroundHubHeader }

import React from "react"
import { LinkBack } from "@/components/atoms/navigation/Link"
import { PageHeader } from "@/components/composites/layout/Page"

/**
 * `SubmissionResultHeader` — the identity band of a graded-result page: a way back
 * to the challenge, plus the requirement's title and description. Sibling of
 * `ContentHeader`, but a result page has left the material — no read-state chip,
 * minutes, or outcomes card, just "where am I, what is this, how do I leave". The
 * breadcrumb slot holds a `LinkBack` composed from `backLabel` + `onBack`. One
 * shape: `isSkeleton` is a state, since only the data changes.
 */

/** Props for {@link SubmissionResultHeader}. */
export interface SubmissionResultHeaderProps {
    /** Back-link label, localized by the caller, e.g. "Back to the solution". */
    backLabel: string
    /** Fired when the learner leaves the result page for the challenge solve page. */
    onBack: () => void
    /** The graded requirement's title. */
    title: string
    /** The requirement's own description/prompt. Omitted → the header ends at the title. */
    description?: string
    /**
     * `true` → every composed atom switches to its own shimmer. The flag FLOWS
     * DOWN into the real atoms (or their skeleton mirror when the atom has none
     * of its own) rather than building a parallel skeleton tree (§12c).
     */
    isSkeleton?: boolean
}

/**
 * Identity band of a graded-result page. See the file header for the full
 * contract and why the breadcrumb slot holds a back-link instead of a trail.
 *
 * @param props - {@link SubmissionResultHeaderProps}
 */
const SubmissionResultHeader = ({
    backLabel,
    onBack,
    title,
    description,
    isSkeleton = false,
}: SubmissionResultHeaderProps) => {
    return (
        <PageHeader
            isSkeleton={isSkeleton}
            breadcrumb={() => (
                <LinkBack label={backLabel} onPress={onBack} isSkeleton={isSkeleton} />
            )}
            title={title}
            description={description}
        />
    )
}

export { SubmissionResultHeader }

"use client"

import React, { useMemo } from "react"
import { ImplementationCard } from "@/components/blocks/learn/lesson/CodeImplementationBody/ImplementationCard"
import { usePersonalProjectGithubForm } from "@/hooks/zustand/personalProjectGithub/usePersonalProjectGithubForm"
import { useAppSelector } from "@/redux/hooks"

/** Props for {@link TaskCodeImplementations}. */
export type TaskCodeImplementationsProps = Record<string, never>
/**
 * Implementation guide for a milestone task, shown for the language picked by the
 * top "grading language" selector in {@link PersonalProjectSubmission} — a single
 * source of truth for the active language, so this section no longer renders its
 * own language tabs. Reuses the lesson implementation card so the look matches.
 *
 * Self-contained: reads `codeImplementations` from redux task state and `lang` from
 * the github form store.
 * @param props - optional className for the root element
 */
export const TaskCodeImplementations = () => {
    // active grading language lives in the shared github-form store (set by the top selector);
    // read-only here, so `enableSync` stays off (default) and no debounced sync runs
    const { lang } = usePersonalProjectGithubForm()

    const selectedTaskId = useAppSelector((state) => state.milestone.selectedTaskId)
    const selectedTaskDetail = useAppSelector((state) => state.milestone.selectedTaskDetail)
    const milestoneEntities = useAppSelector((state) => state.milestone.entities)

    const displayTask = useMemo(() => {
        if (!selectedTaskId) return undefined
        if (selectedTaskDetail?.id === selectedTaskId) {
            return selectedTaskDetail
        }
        for (const milestone of milestoneEntities) {
            const found = milestone.tasks?.find((task) => task.id === selectedTaskId)
            if (found) return found
        }
        return undefined
    }, [selectedTaskId, selectedTaskDetail, milestoneEntities])

    const codeImplementations = displayTask?.codeImplementations ?? []

    // pick the guide for the selected language (lang vocab matches: typescript/java/csharp/go)
    const selected = useMemo(
        () => codeImplementations.find(
            (item) => item.lang?.toLowerCase() === lang?.toLowerCase(),
        ),
        [codeImplementations, lang],
    )

    // no guide authored for the selected language → render nothing for this section
    if (!selected) {
        return null
    }

    // own title dropped — this section now renders under the parent's shared
    // "task.criteriaTitle" LabeledCard (see personal-project/index.tsx) instead of
    // stacking a second hand-rolled header right under the criteria one.
    return <ImplementationCard item={selected} />
}
